return items.map(item => {
  let raw = item.json.output;

  try {
    // Remove ```json or ``` and trim
    raw = raw.replace(/```json|```/g, '').trim();

    const parsed = JSON.parse(raw);

    return {
      json: {
        ...item.json,
        parsedOutput: parsed
      }
    };
  } catch (err) {
    return {
      json: {
        ...item.json,
        parsedOutput: {},
        parse_error: true,
        parse_message: err.message,
        raw_output: raw
      }
    };
  }
});

