parameters.jsCode:
// Agent-Specific Research Node
const input = $('When Executed by Another Workflow').first().json;
const agentHandle = input.target_recipient;
const message = input.output.inputData.text;
const sender = input.output.inputData.sender;

// Base context from orchestrator
let enrichedContext = input.output.inputData.context || '';

// Agent-specific research based on their domain
const agentResearch = {
  'elle': () => {
    // EMBA-specific research
    const keywords = ['assignment', 'class', 'deadline', 'emba', 'course'];
    const found = keywords.filter(k => message.toLowerCase().includes(k));
    if (found.length > 0) {
      enrichedContext += `. EMBA Context: Check current course schedule, assignment deadlines, and recent class discussions`;
    }
  },

  'flex': () => {
    // Fitness-specific research
    if (message.match(/workout|gym|exercise|reps|sets/i)) {
      enrichedContext += `. Fitness Context: Review last workout log, current program phase, recent PRs, and recovery status`;
    }
  },

  'liam': () => {
    // Life strategy research
    if (message.match(/strategy|plan|goal|priority|balance/i)) {
      enrichedContext += `. Strategic Context: Consider current quarterly goals, work-life balance metrics, and recent strategic decisions`;
    }
  },

  'eli': () => {
    // Executive assistant research
    if (message.match(/schedule|meeting|email|follow.?up|task/i)) {
      enrichedContext += `. Assistant Context: Check calendar for conflicts, pending tasks, and recent email threads requiring action`;
    }
  },

  'iris': () => {
    // Daily planning research
    if (message.match(/tomorrow|today|itinerary|schedule|plan/i)) {
      enrichedContext += `. Planning Context: Review calendar, weather, commute times, and energy optimization for the day`;
    }
  }
};

// Execute agent-specific research
if (agentResearch[agentHandle]) {
  agentResearch[agentHandle]();
}

// Add temporal context
const hour = new Date().getHours();
if (hour < 9) {
  enrichedContext += `. Time: Early morning - consider daily planning needs`;
} else if (hour > 20) {
  enrichedContext += `. Time: Evening - consider next-day preparation`;
}

return {
  json: {
    ...input,
    enrichedContext: enrichedContext,
    researchPerformed: true,
    agentDomain: agentHandle
  }
};

